import time, numpy as np
import scipy.linalg as sla
from scipy.linalg import lapack

def bench(fn, size, n=2000):
    A = np.random.normal(size=(size,size))
    fn(A)
    ts=[]
    for _ in range(n):
        A = np.random.normal(size=(size,size))
        t0=time.perf_counter(); fn(A); t1=time.perf_counter()
        ts.append(t1-t0)
    return np.median(ts)*1e6

def ref(A):
    w,v = np.linalg.eig(A)
    i = np.argmax(np.abs(w))
    return w[i], v[:,i]

def eigvals_np(A):
    return np.linalg.eigvals(A)

def scipy_eig(A):
    w,v = sla.eig(A, check_finite=False, overwrite_a=False)
    i=np.argmax(np.abs(w)); return w[i], v[:,i]

def scipy_eigvals(A):
    return sla.eigvals(A, check_finite=False)

def lapack_eigvals(A):
    # dgeev values only
    w, vl, vr, info = lapack.dgeev(A, compute_vl=0, compute_vr=0)
    return w

def lapack_eig_full(A):
    w, vl, vr, info = lapack.dgeev(A, compute_vl=0, compute_vr=1)
    i=np.argmax(np.abs(w)); return w[i], vr[:,i]

for n in [2,4,6,8,10]:
    print(n, "ref", f"{bench(ref,n):.2f}", "eigvals_np", f"{bench(eigvals_np,n):.2f}",
          "scipy_eig", f"{bench(scipy_eig,n):.2f}", "scipy_eigvals", f"{bench(scipy_eigvals,n):.2f}",
          "lapack_vals", f"{bench(lapack_eigvals,n):.2f}", "lapack_full", f"{bench(lapack_eig_full,n):.2f}")
