/*
 * Small dense real-matrix dominant eigenpair.
 *
 * Strategy:
 *   1. Reduce A to upper Hessenberg form with Householder similarity
 *      transformations (eigenvalues are unchanged).
 *   2. Francis implicit double-shift QR on the Hessenberg matrix to get all
 *      eigenvalues (JAMA "hqr" style, eigenvalues only -- no vectors).
 *   3. Pick the eigenvalue of largest modulus.
 *   4. Recover its eigenvector from the *original* A by inverse iteration
 *      with a Rayleigh-quotient shift.  Starting from an already very
 *      accurate eigenvalue this converges to machine precision in 1-2 steps.
 *
 * Everything is self contained (libm only); no LAPACK/BLAS dependency.
 *
 * Exposed as the CPython extension function:
 *      dominant(A) -> (eigenvalue: complex, eigenvector: complex ndarray)
 * and raises a RuntimeError if the QR iteration does not converge, so the
 * caller can fall back to a reference implementation.
 */

#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#include <complex.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

typedef double complex cplx;

/* ------------------------------------------------------------------ */
/* Hessenberg reduction (Householder), in place.                       */
/* ------------------------------------------------------------------ */
static void hessenberg(double *H, int n)
{
    double *ort = (double *)malloc((size_t)n * sizeof(double));
    for (int m = 1; m < n - 1; m++) {
        double scale = 0.0;
        for (int i = m; i < n; i++)
            scale += fabs(H[i * n + (m - 1)]);
        if (scale == 0.0)
            continue;
        double h = 0.0;
        for (int i = n - 1; i >= m; i--) {
            ort[i] = H[i * n + (m - 1)] / scale;
            h += ort[i] * ort[i];
        }
        double g = sqrt(h);
        if (ort[m] > 0.0)
            g = -g;
        h -= ort[m] * g;
        ort[m] -= g;

        for (int j = m; j < n; j++) {
            double f = 0.0;
            for (int i = n - 1; i >= m; i--)
                f += ort[i] * H[i * n + j];
            f /= h;
            for (int i = m; i < n; i++)
                H[i * n + j] -= f * ort[i];
        }
        for (int i = 0; i < n; i++) {
            double f = 0.0;
            for (int j = n - 1; j >= m; j--)
                f += ort[j] * H[i * n + j];
            f /= h;
            for (int j = m; j < n; j++)
                H[i * n + j] -= f * ort[j];
        }
        ort[m] *= scale;
        H[m * n + (m - 1)] = scale * g;
    }
    free(ort);
}

/* ------------------------------------------------------------------ */
/* Francis double-shift QR, eigenvalues only.                          */
/* Returns 0 on success, -1 if it fails to converge.                   */
/* d[i] holds real parts, e[i] imaginary parts (real Schur convention).*/
/* ------------------------------------------------------------------ */
static int hqr_eigenvalues(double *H, int n, double *d, double *e)
{
    int nn, m, l, k, j, its, i, mmin;
    double z = 0.0, y, x, w, v, u, t = 0.0, s, r = 0.0, q = 0.0, p = 0.0, anorm;

    anorm = 0.0;
    for (i = 0; i < n; i++) {
        int j0 = (i - 1 > 0) ? i - 1 : 0;
        for (j = j0; j < n; j++)
            anorm += fabs(H[i * n + j]);
    }

    nn = n - 1;
    t = 0.0;
    while (nn >= 0) {
        its = 0;
        do {
            /* look for a single small subdiagonal element */
            for (l = nn; l >= 1; l--) {
                s = fabs(H[(l - 1) * n + (l - 1)]) + fabs(H[l * n + l]);
                if (s == 0.0)
                    s = anorm;
                if (fabs(H[l * n + (l - 1)]) + s == s) {
                    H[l * n + (l - 1)] = 0.0;
                    break;
                }
            }
            x = H[nn * n + nn];
            if (l == nn) { /* one root found */
                d[nn] = x + t;
                H[nn * n + nn] = x + t;
                e[nn] = 0.0;
                nn--;
                its = 0;
            } else {
                y = H[(nn - 1) * n + (nn - 1)];
                w = H[nn * n + (nn - 1)] * H[(nn - 1) * n + nn];
                if (l == nn - 1) { /* two roots found */
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x = x + t;
                    H[nn * n + nn] = x;
                    H[(nn - 1) * n + (nn - 1)] = y + t;
                    if (q >= 0.0) { /* real pair */
                        z = p + (p >= 0.0 ? z : -z);
                        d[nn - 1] = x + z;
                        d[nn] = d[nn - 1];
                        if (z != 0.0)
                            d[nn] = x - w / z;
                        e[nn - 1] = 0.0;
                        e[nn] = 0.0;
                        x = H[nn * n + (nn - 1)];
                        s = fabs(x) + fabs(z);
                        p = x / s;
                        q = z / s;
                        r = sqrt(p * p + q * q);
                        p /= r;
                        q /= r;
                        for (j = nn - 1; j < n; j++) {
                            z = H[(nn - 1) * n + j];
                            H[(nn - 1) * n + j] = q * z + p * H[nn * n + j];
                            H[nn * n + j] = q * H[nn * n + j] - p * z;
                        }
                        for (i = 0; i <= nn; i++) {
                            z = H[i * n + (nn - 1)];
                            H[i * n + (nn - 1)] = q * z + p * H[i * n + nn];
                            H[i * n + nn] = q * H[i * n + nn] - p * z;
                        }
                    } else { /* complex pair */
                        d[nn - 1] = x + p;
                        d[nn] = x + p;
                        e[nn - 1] = z;
                        e[nn] = -z;
                    }
                    nn -= 2;
                    its = 0;
                } else { /* no convergence yet */
                    if (its == 60)
                        return -1;
                    if (its == 10 || its == 20) {
                        t += x;
                        for (i = 0; i <= nn; i++)
                            H[i * n + i] -= x;
                        s = fabs(H[nn * n + (nn - 1)]) +
                            fabs(H[(nn - 1) * n + (nn - 2)]);
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    /* look for two consecutive small subdiagonal elements */
                    for (m = nn - 2; m >= l; m--) {
                        z = H[m * n + m];
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / H[(m + 1) * n + m] + H[m * n + (m + 1)];
                        q = H[(m + 1) * n + (m + 1)] - z - r - s;
                        r = H[(m + 2) * n + (m + 1)];
                        s = fabs(p) + fabs(q) + fabs(r);
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l)
                            break;
                        u = fabs(H[m * n + (m - 1)]) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(H[(m - 1) * n + (m - 1)]) + fabs(z) +
                                       fabs(H[(m + 1) * n + (m + 1)]));
                        if (u + v == v)
                            break;
                    }
                    for (i = m + 2; i <= nn; i++) {
                        H[i * n + (i - 2)] = 0.0;
                        if (i != m + 2)
                            H[i * n + (i - 3)] = 0.0;
                    }
                    /* double QR step involving rows l..nn and columns m..nn */
                    for (k = m; k <= nn - 1; k++) {
                        if (k != m) {
                            p = H[k * n + (k - 1)];
                            q = H[(k + 1) * n + (k - 1)];
                            r = (k != nn - 1) ? H[(k + 2) * n + (k - 1)] : 0.0;
                            x = fabs(p) + fabs(q) + fabs(r);
                            if (x == 0.0)
                                continue;
                            p /= x;
                            q /= x;
                            r /= x;
                        }
                        s = sqrt(p * p + q * q + r * r);
                        if (p < 0.0)
                            s = -s;
                        if (s != 0.0) {
                            if (k != m)
                                H[k * n + (k - 1)] = -s * x;
                            else if (l != m)
                                H[k * n + (k - 1)] = -H[k * n + (k - 1)];
                            p += s;
                            x = p / s;
                            y = q / s;
                            z = r / s;
                            q /= p;
                            r /= p;
                            for (j = k; j < n; j++) {
                                p = H[k * n + j] + q * H[(k + 1) * n + j];
                                if (k != nn - 1) {
                                    p += r * H[(k + 2) * n + j];
                                    H[(k + 2) * n + j] -= p * z;
                                }
                                H[(k + 1) * n + j] -= p * y;
                                H[k * n + j] -= p * x;
                            }
                            mmin = (nn < k + 3) ? nn : k + 3;
                            for (i = 0; i <= mmin; i++) {
                                p = x * H[i * n + k] + y * H[i * n + (k + 1)];
                                if (k != nn - 1) {
                                    p += z * H[i * n + (k + 2)];
                                    H[i * n + (k + 2)] -= p * r;
                                }
                                H[i * n + (k + 1)] -= p * q;
                                H[i * n + k] -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Complex LU with partial pivoting, solves A x = b in place (b -> x). */
/* Returns 0 on success.                                               */
/* ------------------------------------------------------------------ */
static int cmplx_lu_solve(cplx *M, int n, cplx *b)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double best = cabs(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double v = cabs(M[i * n + k]);
            if (v > best) {
                best = v;
                p = i;
            }
        }
        if (p != k) {
            for (int j = 0; j < n; j++) {
                cplx t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            cplx t = b[k];
            b[k] = b[p];
            b[p] = t;
        }
        cplx d = M[k * n + k];
        if (cabs(d) == 0.0)
            return -1;
        cplx inv = 1.0 / d;
        for (int i = k + 1; i < n; i++) {
            cplx f = M[i * n + k] * inv;
            M[i * n + k] = f;
            for (int j = k + 1; j < n; j++)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; i--) {
        cplx s = b[i];
        for (int j = i + 1; j < n; j++)
            s -= M[i * n + j] * b[j];
        cplx d = M[i * n + i];
        if (cabs(d) == 0.0)
            return -1;
        b[i] = s / d;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Inverse iteration with Rayleigh-quotient shifts.                    */
/* On entry x holds a starting vector; on exit a unit-norm eigenvector */
/* estimate.  Returns the residual ||A x - lambda x|| of the returned  */
/* pair (with lambda set to the Rayleigh quotient), or -1 on failure.  */
/* ------------------------------------------------------------------ */
static double inverse_iteration(const double *A, int n, cplx lam,
                                cplx *x, double anorm)
{
    cplx *M = (cplx *)malloc((size_t)n * n * sizeof(cplx));
    cplx *b = (cplx *)malloc((size_t)n * sizeof(cplx));
    cplx *Ax = (cplx *)malloc((size_t)n * sizeof(cplx));
    double res = -1.0;

    /* Start with a uniform (generic) right-hand side. */
    for (int i = 0; i < n; i++)
        b[i] = 1.0 + 0.0 * I;

    double delta = 1e-13 * anorm;
    for (int iter = 0; iter < 3; iter++) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                M[i * n + j] = (cplx)A[i * n + j];
        for (int i = 0; i < n; i++)
            M[i * n + i] -= lam;
        /* Tiny shift keeps the nearly singular system solvable. */
        for (int i = 0; i < n; i++)
            M[i * n + i] += delta;

        if (cmplx_lu_solve(M, n, b) != 0)
            goto done;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += creal(b[i]) * creal(b[i]) + cimag(b[i]) * cimag(b[i]);
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            goto done;
        for (int i = 0; i < n; i++)
            b[i] /= nrm;

        /* Rayleigh quotient of the current vector. */
        cplx rho = 0.0;
        for (int i = 0; i < n; i++) {
            cplx s = 0.0;
            for (int j = 0; j < n; j++)
                s += (cplx)A[i * n + j] * b[j];
            Ax[i] = s;
            rho += conj(b[i]) * s;
        }
        lam = rho;
        /* Shrink the regularisation as the shift gets accurate. */
        delta = (iter == 0) ? 1e-13 * anorm : 1e-15 * anorm;

        /* residual of the current pair */
        double rs = 0.0;
        for (int i = 0; i < n; i++) {
            cplx r = Ax[i] - lam * b[i];
            rs += creal(r) * creal(r) + cimag(r) * cimag(r);
        }
        res = sqrt(rs);
    }

    for (int i = 0; i < n; i++)
        x[i] = b[i];

done:
    free(M);
    free(b);
    free(Ax);
    return res;
}

/* ------------------------------------------------------------------ */
/* Core routine: A is row-major n x n (n >= 1).                        */
/* ------------------------------------------------------------------ */
static int dominant_eigenpair(const double *A, int n, cplx *out_lam,
                              cplx *out_vec)
{
    double *H = (double *)malloc((size_t)n * n * sizeof(double));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    double *e = (double *)malloc((size_t)n * sizeof(double));
    cplx *x = (cplx *)malloc((size_t)n * sizeof(cplx));
    int status = -1;

    double anorm = 0.0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            anorm += fabs(A[i * n + j]);
    if (anorm == 0.0) {
        out_lam[0] = 0.0;
        for (int i = 0; i < n; i++)
            out_vec[i] = (i == 0) ? 1.0 : 0.0;
        status = 0;
        goto cleanup;
    }

    if (n == 1) {
        out_lam[0] = A[0];
        out_vec[0] = 1.0;
        status = 0;
        goto cleanup;
    }

    memcpy(H, A, (size_t)n * n * sizeof(double));
    hessenberg(H, n);
    if (hqr_eigenvalues(H, n, d, e) != 0)
        goto cleanup;

    /* dominant eigenvalue by modulus */
    int idx = 0;
    double best = -1.0;
    for (int i = 0; i < n; i++) {
        double m = d[i] * d[i] + e[i] * e[i];
        if (m > best) {
            best = m;
            idx = i;
        }
    }
    cplx lam = d[idx] + e[idx] * I;

    for (int i = 0; i < n; i++)
        x[i] = 1.0;
    double res = inverse_iteration(A, n, lam, x, anorm);
    if (res < 0.0 || !isfinite(res))
        goto cleanup;

    /* Final Rayleigh quotient for the returned pair. */
    cplx rho = 0.0;
    for (int i = 0; i < n; i++) {
        cplx s = 0.0;
        for (int j = 0; j < n; j++)
            s += (cplx)A[i * n + j] * x[j];
        rho += conj(x[i]) * s;
    }
    out_lam[0] = rho;
    memcpy(out_vec, x, (size_t)n * sizeof(cplx));
    status = 0;

cleanup:
    free(H);
    free(d);
    free(e);
    free(x);
    return status;
}

/* ------------------------------------------------------------------ */
/* Python wrapper                                                      */
/* ------------------------------------------------------------------ */
static PyObject *py_dominant(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (arr == NULL)
        return NULL;

    if (PyArray_NDIM(arr) != 2 ||
        PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1) ||
        PyArray_DIM(arr, 0) < 1) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected a non-empty square matrix");
        return NULL;
    }

    int n = (int)PyArray_DIM(arr, 0);
    const double *A = (const double *)PyArray_DATA(arr);

    cplx lam;
    cplx *vec = (cplx *)malloc((size_t)n * sizeof(cplx));
    if (vec == NULL) {
        Py_DECREF(arr);
        return PyErr_NoMemory();
    }

    int status = dominant_eigenpair(A, n, &lam, vec);
    Py_DECREF(arr);
    if (status != 0) {
        free(vec);
        PyErr_SetString(PyExc_RuntimeError, "eigenvalue iteration failed");
        return NULL;
    }

    npy_intp dims[1] = {n};
    PyArrayObject *out = (PyArrayObject *)PyArray_SimpleNew(1, dims,
                                                            NPY_COMPLEX128);
    if (out == NULL) {
        free(vec);
        return NULL;
    }
    memcpy(PyArray_DATA(out), vec, (size_t)n * sizeof(cplx));
    free(vec);

    PyObject *lam_obj = PyComplex_FromDoubles(creal(lam), cimag(lam));
    if (lam_obj == NULL) {
        Py_DECREF((PyObject *)out);
        return NULL;
    }
    PyObject *ret = PyTuple_Pack(2, lam_obj, (PyObject *)out);
    Py_DECREF(lam_obj);
    Py_DECREF((PyObject *)out);
    return ret;
}

static PyMethodDef methods[] = {
    {"dominant", py_dominant, METH_O,
     "dominant(A) -> (eigenvalue, eigenvector) of largest-modulus eigenvalue"},
    {NULL, NULL, 0, NULL}};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_dom_eig",
    "Fast dominant eigenpair for small dense real matrices.", -1, methods};

PyMODINIT_FUNC PyInit__dom_eig(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}

