input.content:
/*
 * Small dense real-matrix dominant eigenpair.
 *
 * Strategy:
 *   1. Reduce A to upper Hessenberg form with Householder similarity
 *      transformations (eigenvalues are unchanged).
 *   2. Francis implicit double-shift QR on the Hessenberg matrix to get all
 *      eigenvalues (JAMA "hqr" style, eigenvalues only -- no vectors).
 *   3. Pick the eigenvalue of largest modulus.
 *   4. Recover its eigenvector from the *original* A by inverse iteration
 *      with Rayleigh-quotient shifts.  The QR eigenvalue is already accurate
 *      to working precision, so one or two solves give a machine-precision
 *      eigenpair.  Real eigenvalues use a real solve, complex ones complex.
 *
 * Everything is self contained (libm only); no LAPACK/BLAS dependency.
 *
 * Exposed as the CPython extension function:
 *      dominant(A) -> (eigenvalue: complex, eigenvector: complex ndarray)
 * and raises a RuntimeError if the QR iteration does not converge, so the
 * caller can fall back to a reference implementation.
 */

#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>

#include <complex.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

typedef double complex cplx;

/* Stack buffers cover the documented sizes (n <= 10) without any heap use. */
#define STACK_N 32

/* ------------------------------------------------------------------ */
/* Hessenberg reduction (Householder), in place.                       */
/* ------------------------------------------------------------------ */
static void hessenberg(double *H, int n, double *ort)
{
    for (int m = 1; m < n - 1; m++) {
        double scale = 0.0;
        for (int i = m; i < n; i++)
            scale += fabs(H[i * n + (m - 1)]);
        if (scale == 0.0)
            continue;
        double h = 0.0;
        for (int i = n - 1; i >= m; i--) {
            ort[i] = H[i * n + (m - 1)] / scale;
            h += ort[i] * ort[i];
        }
        double g = sqrt(h);
        if (ort[m] > 0.0)
            g = -g;
        h -= ort[m] * g;
        ort[m] -= g;

        for (int j = m; j < n; j++) {
            double f = 0.0;
            for (int i = n - 1; i >= m; i--)
                f += ort[i] * H[i * n + j];
            f /= h;
            for (int i = m; i < n; i++)
                H[i * n + j] -= f * ort[i];
        }
        for (int i = 0; i < n; i++) {
            double f = 0.0;
            for (int j = n - 1; j >= m; j--)
                f += ort[j] * H[i * n + j];
            f /= h;
            for (int j = m; j < n; j++)
                H[i * n + j] -= f * ort[j];
        }
        ort[m] *= scale;
        H[m * n + (m - 1)] = scale * g;
    }
}

/* ------------------------------------------------------------------ */
/* Francis double-shift QR, eigenvalues only.                          */
/* Returns 0 on success, -1 if it fails to converge.                   */
/* d[i] holds real parts, e[i] imaginary parts (real Schur convention).*/
/* ------------------------------------------------------------------ */
static int hqr_eigenvalues(double *H, int n, double *d, double *e)
{
    int nn, m, l, k, j, its, i, mmin;
    double z = 0.0, y, x, w, v, u, t = 0.0, s, r = 0.0, q = 0.0, p = 0.0, anorm;

    anorm = 0.0;
    for (i = 0; i < n; i++) {
        int j0 = (i - 1 > 0) ? i - 1 : 0;
        for (j = j0; j < n; j++)
            anorm += fabs(H[i * n + j]);
    }

    nn = n - 1;
    t = 0.0;
    while (nn >= 0) {
        its = 0;
        do {
            /* look for a single small subdiagonal element */
            for (l = nn; l >= 1; l--) {
                s = fabs(H[(l - 1) * n + (l - 1)]) + fabs(H[l * n + l]);
                if (s == 0.0)
                    s = anorm;
                if (fabs(H[l * n + (l - 1)]) + s == s) {
                    H[l * n + (l - 1)] = 0.0;
                    break;
                }
            }
            x = H[nn * n + nn];
            if (l == nn) { /* one root found */
                d[nn] = x + t;
                H[nn * n + nn] = x + t;
                e[nn] = 0.0;
                nn--;
                its = 0;
            } else {
                y = H[(nn - 1) * n + (nn - 1)];
                w = H[nn * n + (nn - 1)] * H[(nn - 1) * n + nn];
                if (l == nn - 1) { /* two roots found */
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x = x + t;
                    H[nn * n + nn] = x;
                    H[(nn - 1) * n + (nn - 1)] = y + t;
                    if (q >= 0.0) { /* real pair */
                        z = p + (p >= 0.0 ? z : -z);
                        d[nn - 1] = x + z;
                        d[nn] = d[nn - 1];
                        if (z != 0.0)
                            d[nn] = x - w / z;
                        e[nn - 1] = 0.0;
                        e[nn] = 0.0;
                        x = H[nn * n + (nn - 1)];
                        s = fabs(x) + fabs(z);
                        p = x / s;
                        q = z / s;
                        r = sqrt(p * p + q * q);
                        p /= r;
                        q /= r;
                        for (j = nn - 1; j < n; j++) {
                            z = H[(nn - 1) * n + j];
                            H[(nn - 1) * n + j] = q * z + p * H[nn * n + j];
                            H[nn * n + j] = q * H[nn * n + j] - p * z;
                        }
                        for (i = 0; i <= nn; i++) {
                            z = H[i * n + (nn - 1)];
                            H[i * n + (nn - 1)] = q * z + p * H[i * n + nn];
                            H[i * n + nn] = q * H[i * n + nn] - p * z;
                        }
                    } else { /* complex pair */
                        d[nn - 1] = x + p;
                        d[nn] = x + p;
                        e[nn - 1] = z;
                        e[nn] = -z;
                    }
                    nn -= 2;
                    its = 0;
                } else { /* no convergence yet */
                    if (its == 60)
                        return -1;
                    if (its == 10 || its == 20) {
                        t += x;
                        for (i = 0; i <= nn; i++)
                            H[i * n + i] -= x;
                        s = fabs(H[nn * n + (nn - 1)]) +
                            fabs(H[(nn - 1) * n + (nn - 2)]);
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    /* look for two consecutive small subdiagonal elements */
                    for (m = nn - 2; m >= l; m--) {
                        z = H[m * n + m];
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / H[(m + 1) * n + m] + H[m * n + (m + 1)];
                        q = H[(m + 1) * n + (m + 1)] - z - r - s;
                        r = H[(m + 2) * n + (m + 1)];
                        s = fabs(p) + fabs(q) + fabs(r);
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l)
                            break;
                        u = fabs(H[m * n + (m - 1)]) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(H[(m - 1) * n + (m - 1)]) + fabs(z) +
                                       fabs(H[(m + 1) * n + (m + 1)]));
                        if (u + v == v)
                            break;
                    }
                    for (i = m + 2; i <= nn; i++) {
                        H[i * n + (i - 2)] = 0.0;
                        if (i != m + 2)
                            H[i * n + (i - 3)] = 0.0;
                    }
                    /* double QR step involving rows l..nn and columns m..nn */
                    for (k = m; k <= nn - 1; k++) {
                        if (k != m) {
                            p = H[k * n + (k - 1)];
                            q = H[(k + 1) * n + (k - 1)];
                            r = (k != nn - 1) ? H[(k + 2) * n + (k - 1)] : 0.0;
                            x = fabs(p) + fabs(q) + fabs(r);
                            if (x == 0.0)
                                continue;
                            p /= x;
                            q /= x;
                            r /= x;
                        }
                        s = sqrt(p * p + q * q + r * r);
                        if (p < 0.0)
                            s = -s;
                        if (s != 0.0) {
                            if (k != m)
                                H[k * n + (k - 1)] = -s * x;
                            else if (l != m)
                                H[k * n + (k - 1)] = -H[k * n + (k - 1)];
                            p += s;
                            x = p / s;
                            y = q / s;
                            z = r / s;
                            q /= p;
                            r /= p;
                            for (j = k; j < n; j++) {
                                p = H[k * n + j] + q * H[(k + 1) * n + j];
                                if (k != nn - 1) {
                                    p += r * H[(k + 2) * n + j];
                                    H[(k + 2) * n + j] -= p * z;
                                }
                                H[(k + 1) * n + j] -= p * y;
                                H[k * n + j] -= p * x;
                            }
                            mmin = (nn < k + 3) ? nn : k + 3;
                            for (i = 0; i <= mmin; i++) {
                                p = x * H[i * n + k] + y * H[i * n + (k + 1)];
                                if (k != nn - 1) {
                                    p += z * H[i * n + (k + 2)];
                                    H[i * n + (k + 2)] -= p * r;
                                }
                                H[i * n + (k + 1)] -= p * q;
                                H[i * n + k] -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Real LU with partial pivoting; solves M x = b in place.            */
/* Returns 0 on success.                                              */
/* ------------------------------------------------------------------ */
static int real_lu_solve(double *M, int n, double *b)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double best = fabs(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double v = fabs(M[i * n + k]);
            if (v > best) {
                best = v;
                p = i;
            }
        }
        if (p != k) {
            for (int j = 0; j < n; j++) {
                double t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            double t = b[k];
            b[k] = b[p];
            b[p] = t;
        }
        double d = M[k * n + k];
        if (d == 0.0)
            return -1;
        double inv = 1.0 / d;
        for (int i = k + 1; i < n; i++) {
            double f = M[i * n + k] * inv;
            M[i * n + k] = f;
            for (int j = k + 1; j < n; j++)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; i--) {
        double s = b[i];
        for (int j = i + 1; j < n; j++)
            s -= M[i * n + j] * b[j];
        double d = M[i * n + i];
        if (d == 0.0)
            return -1;
        b[i] = s / d;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Complex LU with partial pivoting; solves M x = b in place.         */
/* ------------------------------------------------------------------ */
static int cmplx_lu_solve(cplx *M, int n, cplx *b)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double best = creal(M[k * n + k]) * creal(M[k * n + k]) +
                      cimag(M[k * n + k]) * cimag(M[k * n + k]);
        for (int i = k + 1; i < n; i++) {
            double re = creal(M[i * n + k]), im = cimag(M[i * n + k]);
            double v = re * re + im * im;
            if (v > best) {
                best = v;
                p = i;
            }
        }
        if (p != k) {
            for (int j = 0; j < n; j++) {
                cplx t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            cplx t = b[k];
            b[k] = b[p];
            b[p] = t;
        }
        cplx d = M[k * n + k];
        double dd = creal(d) * creal(d) + cimag(d) * cimag(d);
        if (dd == 0.0)
            return -1;
        cplx inv = conj(d) / dd;
        for (int i = k + 1; i < n; i++) {
            cplx f = M[i * n + k] * inv;
            M[i * n + k] = f;
            for (int j = k + 1; j < n; j++)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; i--) {
        cplx s = b[i];
        for (int j = i + 1; j < n; j++)
            s -= M[i * n + j] * b[j];
        cplx d = M[i * n + i];
        double dd = creal(d) * creal(d) + cimag(d) * cimag(d);
        if (dd == 0.0)
            return -1;
        b[i] = s * conj(d) / dd;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Eigenvector for a real eigenvalue, using real arithmetic.          */
/* Returns the residual ||A x - rho x|| for the unit vector x.        */
/* ------------------------------------------------------------------ */
static double inviter_real(const double *A, int n, double lam, double *x,
                           double anorm, double *M, double *b, double *Ax)
{
    double delta = 1e-13 * anorm;
    double res = -1.0;

    for (int i = 0; i < n; i++)
        b[i] = 1.0;

    for (int iter = 0; iter < 3; iter++) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                M[i * n + j] = A[i * n + j];
        for (int i = 0; i < n; i++)
            M[i * n + i] += delta - lam;

        if (real_lu_solve(M, n, b) != 0)
            return -1.0;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += b[i] * b[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return -1.0;
        double inv_nrm = 1.0 / nrm;
        for (int i = 0; i < n; i++)
            b[i] *= inv_nrm;

        double rho = 0.0, rs = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            for (int j = 0; j < n; j++)
                s += A[i * n + j] * b[j];
            Ax[i] = s;
            rho += b[i] * s;
        }
        for (int i = 0; i < n; i++) {
            double r = Ax[i] - rho * b[i];
            rs += r * r;
        }
        res = sqrt(rs);
        lam = rho;
        for (int i = 0; i < n; i++)
            x[i] = b[i];

        if (res <= 1e-13 * anorm)
            break;
        delta = 1e-15 * anorm;
    }
    return res;
}

/* ------------------------------------------------------------------ */
/* Eigenvector for a complex eigenvalue, using complex arithmetic.    */
/* ------------------------------------------------------------------ */
static double inviter_cmplx(const double *A, int n, cplx lam, cplx *x,
                            double anorm, cplx *M, cplx *b, cplx *Ax)
{
    double delta = 1e-13 * anorm;
    double res = -1.0;

    for (int i = 0; i < n; i++)
        b[i] = 1.0;

    for (int iter = 0; iter < 3; iter++) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                M[i * n + j] = (cplx)A[i * n + j];
        for (int i = 0; i < n; i++)
            M[i * n + i] += delta - lam;

        if (cmplx_lu_solve(M, n, b) != 0)
            return -1.0;

        double nrm = 0.0;
        for (int i = 0; i < n; i++)
            nrm += creal(b[i]) * creal(b[i]) + cimag(b[i]) * cimag(b[i]);
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm))
            return -1.0;
        cplx inv_nrm = 1.0 / nrm;
        for (int i = 0; i < n; i++)
            b[i] *= inv_nrm;

        cplx rho = 0.0;
        double rs = 0.0;
        for (int i = 0; i < n; i++) {
            cplx s = 0.0;
            for (int j = 0; j < n; j++)
                s += (cplx)A[i * n + j] * b[j];
            Ax[i] = s;
            rho += conj(b[i]) * s;
        }
        for (int i = 0; i < n; i++) {
            cplx r = Ax[i] - rho * b[i];
            rs += creal(r) * creal(r) + cimag(r) * cimag(r);
        }
        res = sqrt(rs);
        lam = rho;
        for (int i = 0; i < n; i++)
            x[i] = b[i];

        if (res <= 1e-13 * anorm)
            break;
        delta = 1e-15 * anorm;
    }
    return res;
}

/* ------------------------------------------------------------------ */
/* Core routine: A is row-major n x n (n >= 1).                        */
/* ------------------------------------------------------------------ */
#define BUFSZ (STACK_N * STACK_N)

static int dominant_eigenpair(const double *A, int n, cplx *out_lam,
                              cplx *out_vec)
{
    double Hb[BUFSZ], db[STACK_N], eb[STACK_N], ortb[STACK_N];
    double Mb[BUFSZ], bb[STACK_N], Axb[STACK_N];
    cplx Mzb[BUFSZ], bzb[STACK_N], Axzb[STACK_N], xzb[STACK_N];

    double *H = Hb, *d = db, *e = eb, *ort = ortb;
    double *M = Mb, *b = bb, *Ax = Axb;
    cplx *Mz = Mzb, *bz = bzb, *Axz = Axzb, *xz = xzb;
    int heap = 0;
    int status = -1;

    if (n > STACK_N) {
        H = malloc((size_t)n * n * sizeof(double));
        d = malloc((size_t)n * sizeof(double));
        e = malloc((size_t)n * sizeof(double));
