        bz = malloc((size_t)n * sizeof(cplx));
        Axz = malloc((size_t)n * sizeof(cplx));
        xz = malloc((size_t)n * sizeof(cplx));
        heap = 1;
        if (!H || !d || !e || !ort || !M || !b || !Ax || !Mz || !bz || !Axz ||
            !xz) {
            status = -1;
            goto cleanup;
        }
    }

    double anorm = 0.0;
    for (int i = 0; i < n * n; i++)
        anorm += fabs(A[i]);
    if (anorm == 0.0) {
        out_lam[0] = 0.0;
        for (int i = 0; i < n; i++)
            out_vec[i] = (i == 0) ? 1.0 : 0.0;
        status = 0;
        goto cleanup;
    }

    if (n == 1) {
        out_lam[0] = A[0];
        out_vec[0] = 1.0;
        status = 0;
        goto cleanup;
    }

    memcpy(H, A, (size_t)n * n * sizeof(double));
    hessenberg(H, n, ort);
    if (hqr_eigenvalues(H, n, d, e) != 0)
        goto cleanup;

