    int idx = 0;
    double best = -1.0;
    for (int i = 0; i < n; i++) {
        double m = d[i] * d[i] + e[i] * e[i];
        if (m > best) {
            best = m;
            idx = i;
        }
    }

    if (e[idx] == 0.0) {
        /* real eigenvalue: real arithmetic */
        if (inviter_real(A, n, d[idx], b, anorm, M, b, Ax) < 0.0)
            goto cleanup;
        double rho = 0.0;
        for (int i = 0; i < n; i++) {
            double s = 0.0;
            for (int j = 0; j < n; j++)
                s += A[i * n + j] * b[j];
            rho += b[i] * s;
        }
        out_lam[0] = rho;
        for (int i = 0; i < n; i++)
            out_vec[i] = b[i];
    } else {
        /* complex eigenvalue: complex arithmetic */
        cplx lam = d[idx] + e[idx] * I;
        for (int i = 0; i < n; i++)
            xz[i] = 1.0;
        double res = inviter_cmplx(A, n, lam, xz, anorm, Mz, bz, Axz);
        if (res < 0.0 || !isfinite(res))
            goto cleanup;
        cplx rho = 0.0;
        for (int i = 0; i < n; i++) {
            cplx s = 0.0;
            for (int j = 0; j < n; j++)
                s += (cplx)A[i * n + j] * xz[j];
            rho += conj(xz[i]) * s;
        }
        out_lam[0] = rho;
        for (int i = 0; i < n; i++)
            out_vec[i] = xz[i];
    }
    status = 0;

cleanup:
    if (heap) {
        free(H);
        free(d);
        free(e);
        free(ort);
        free(M);
        free(b);
        free(Ax);
        free(Mz);
        free(bz);
        free(Axz);
        free(xz);
    }
    return status;
}

