static PyObject *py_dominant(PyObject *self, PyObject *arg)
{
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (arr == NULL)
        return NULL;

    if (PyArray_NDIM(arr) != 2 ||
        PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1) ||
        PyArray_DIM(arr, 0) < 1) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected a non-empty square matrix");
        return NULL;
    }

    int n = (int)PyArray_DIM(arr, 0);
    const double *A = (const double *)PyArray_DATA(arr);

    cplx lam;
    npy_intp dims[1] = {n};
    PyArrayObject *out = (PyArrayObject *)PyArray_SimpleNew(1, dims,
                                                            NPY_COMPLEX128);
    if (out == NULL) {
        Py_DECREF(arr);
        return NULL;
    }

    int status = dominant_eigenpair(A, n, &lam, (cplx *)PyArray_DATA(out));
    Py_DECREF(arr);
    if (status != 0) {
        Py_DECREF((PyObject *)out);
        PyErr_SetString(PyExc_RuntimeError, "eigenvalue iteration failed");
        return NULL;
    }

    PyObject *lam_obj = PyComplex_FromDoubles(creal(lam), cimag(lam));
    if (lam_obj == NULL) {
        Py_DECREF((PyObject *)out);
        return NULL;
    }
    PyObject *ret = PyTuple_Pack(2, lam_obj, (PyObject *)out);
    Py_DECREF(lam_obj);
    Py_DECREF((PyObject *)out);
    return ret;
}

